        pub fn pendingRowPolicyReceipt(self: anytype) !?row_policy_bundle_mod.Receipt {
            const bytes = self.core.store.get(self.alloc, row_policy_bundle_mod.pending_key) catch |err| switch (err) {
                error.NotFound => return null,
