        pub fn encodeStoreLookupKeyAlloc(self: anytype, alloc: Allocator, key: []const u8) ![]u8 {
            // Point reads deliberately avoid the global apply lock. Fence before
            // consulting the runtime schema so a native generation swap cannot encode
            // a lookup with the old keyspace and execute it against the new store.
            if (self.core.store.portableImportPublicationInProgress()) {
                return error.PortableImportPublicationInProgress;
            }
            if (internal_keys.isInternalUserKey(key) or std.mem.startsWith(u8, key, "\x00\x00__metadata__:") or isSplitMetadataKey(key)) {
                return try alloc.dupe(u8, key);
            }
            var schema_view = self.core.acquireSchemaView();
            defer if (schema_view) |*view| view.release();
            return try encodeStoreLookupKeyWithPinnedSchemaAlloc(self, alloc, key, schema_view);
        }
        pub fn encodeStoreLookupKeyWithPinnedSchemaAlloc(
            self: anytype,
            alloc: Allocator,
            key: []const u8,
            schema_view: ?schema_registry_mod.SchemaView,
        ) ![]u8 {
            if (self.core.store.portableImportPublicationInProgress())
                return error.PortableImportPublicationInProgress;
            if (internal_keys.isInternalUserKey(key) or std.mem.startsWith(u8, key, "\x00\x00__metadata__:") or isSplitMetadataKey(key))
                return try alloc.dupe(u8, key);
            if (schema_view) |view| {
                if (view.storageMode() == .relational) return try relational_store.keyAlloc(alloc, key);
            }
            return try internal_keys.documentKeyAlloc(alloc, key);
        }
        pub fn encodeThinReplayRecordPayload(
            alloc: Allocator,
            req: types.BatchRequest,
            extracted: []const mapper.ExtractedWrite,
            deleted_artifact_keys: []const []u8,
            changed_artifact_keys: []const []u8,
            overwritten_flags: []const bool,
            derived_changed_flags: []const bool,
            sequence: u64,
            include_generated_enrichment_hint: bool,
            index_manager: ?*index_manager_mod.IndexManager,
            sync_targets_out: ?*ManagedSyncTargets,
            owning_table: ?[]const u8,
        ) ![]u8 {
            if ((index_manager == null) != (sync_targets_out == null)) return error.InvalidArgument;
            if (derived_changed_flags.len != req.writes.len) return error.InvalidArgument;
            var changed_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
            var changed_doc_key_set = std.StringHashMapUnmanaged(void).empty;
            errdefer {
                for (changed_doc_keys.items) |key| alloc.free(@constCast(key));
                changed_doc_keys.deinit(alloc);
            }
            var deleted_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
            var deleted_doc_key_set = std.StringHashMapUnmanaged(void).empty;
            errdefer {
                for (deleted_doc_keys.items) |key| alloc.free(@constCast(key));
                deleted_doc_keys.deinit(alloc);
            }
            var overwritten_doc_keys = std.ArrayListUnmanaged([]const u8).empty;
            var overwritten_doc_key_set = std.StringHashMapUnmanaged(void).empty;
            errdefer {
                for (overwritten_doc_keys.items) |key| alloc.free(@constCast(key));
                overwritten_doc_keys.deinit(alloc);
            }
            var thin_changed_artifact_keys = std.ArrayListUnmanaged([]const u8).empty;
            var thin_changed_artifact_key_set = std.StringHashMapUnmanaged(void).empty;
            errdefer {
                for (thin_changed_artifact_keys.items) |key| alloc.free(@constCast(key));
                thin_changed_artifact_keys.deinit(alloc);
            }
            var target_hints = std.ArrayListUnmanaged(change_journal_mod.TargetHint).empty;
            errdefer target_hints.deinit(alloc);
            defer {
                changed_doc_key_set.deinit(alloc);
                deleted_doc_key_set.deinit(alloc);
                overwritten_doc_key_set.deinit(alloc);
                thin_changed_artifact_key_set.deinit(alloc);
            }

            var saw_overwritten = false;

            for (req.writes, 0..) |write, i| {
                if (!derived_changed_flags[i]) continue;
                const extracted_write = extracted[i];
                // PR #957 review, blocker 8: a write with no content (an
                // `_edges`-only document is one shape; an `_embeddings`-only write
                // is another) can never match a generated enrichment request --
                // those are declared against document FIELDS, and a content-less
                // write has none to chunk or embed. Gating this whole block on
                // hasDocument() (rather than waking the enrichment worker for
                // every write whenever any generated-enrichment target exists)
                // keeps that content-less write's key out of changed_doc_keys
                // entirely. Recording it there would otherwise put the #938 fix
                // right back where it started: full-text/algebraic replay also
                // consumes this list, and once this batch's OTHER writes give the
                // record a full_text hint, it would wait forever for a primary row
                // this key will never have.
                if (extracted_write.hasDocument()) {
                    try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, write.key);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
                    if (include_generated_enrichment_hint) {
                        try appendUniqueReplayRecordHint(alloc, &target_hints, .enrichment);
                    }
                }

                for (extracted_write.dense_embeddings) |embedding| {
                    if (embedding.artifact_key) |artifact_key| try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
                }
                for (extracted_write.sparse_embeddings) |embedding| {
                    if (embedding.artifact_key) |artifact_key| try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
                }
                if (extracted_write.mentioned_graph_indexes.len > 0 or extracted_write.graph_writes.len > 0) {
                    // Graph-only content (an `_edges`-only document, for example) has
                    // no full-text/dense/sparse/algebraic payload. changed_doc_keys
                    // feeds those replay workers, which reconstruct a synthetic
                    // upsert for every key it contains and expect to find a primary
                    // row. A document whose only content is edges never has one, so
                    // recording its key here would make full-text replay retry
                    // ReplayDocumentNotVisible forever (issue #938). The graph
                    // worker replays this change through changed_artifact_keys
                    // instead, so only the hint belongs here.
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
                }
                if (overwritten_flags[i] and extracted_write.hasDocument()) {
                    try appendUniqueReplayRecordKeyWithSet(alloc, &overwritten_doc_keys, &overwritten_doc_key_set, write.key);
                    saw_overwritten = true;
                }
            }

            if (saw_overwritten) {
                try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
            }

            for (changed_artifact_keys) |key| {
                try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, key);
                if (internal_keys.isEmbeddingArtifactKey(key) or internal_keys.isDerivedEmbeddingArtifactKey(key)) {
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
                }
                if (internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                if (internal_keys.isGraphEdgeArtifactKey(key) or internal_keys.isAssetArtifactKey(key) or internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
                if (internal_keys.isAssetArtifactKey(key)) {
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .resolution);
                }
                // A committed resolution artifact re-drives sibling resolvers over
                // the same source (compositional event identity composes sibling
                // canonical keys). The runtime maps the key back to its source
                // extraction; byte-stable recomputes emit no further resolution
                // record, so the fan-back terminates.
                if (internal_keys.isResolutionArtifactKey(key)) {
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .resolution);
                }
            }

            for (req.graph_writes) |write| {
                try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, if (write.owner_document.len > 0) write.owner_document else if (write.owner.len > 0) write.owner else write.source);
                const artifact_key = try internal_keys.graphRelationshipArtifactKeyAlloc(alloc, if (write.owner_document.len > 0) write.owner_document else if (write.owner.len > 0) write.owner else write.source, write.index_name, write.edge_type, write.target, write.source, write.edge_id);
                defer alloc.free(artifact_key);
                try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
            }
            for (req.graph_deletes) |delete| {
                // An edge deletion changes the source document's graph projection; it
                // does not delete the source document. Classifying it as a document
                // deletion makes graph replay clear every source edge before applying
                // the targeted artifact delta.
                try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, if (delete.owner_document.len > 0) delete.owner_document else if (delete.owner.len > 0) delete.owner else delete.source);
                const artifact_key = try internal_keys.graphRelationshipArtifactKeyAlloc(alloc, if (delete.owner_document.len > 0) delete.owner_document else if (delete.owner.len > 0) delete.owner else delete.source, delete.index_name, delete.edge_type, delete.target, delete.source, delete.edge_id);
                defer alloc.free(artifact_key);
                try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, artifact_key);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
            }

            var neighbor_hints = hints: {
                const active = index_manager orelse break :hints NeighborContextReplayHints{};
                if (!active.hasAssetNeighborContext()) break :hints NeighborContextReplayHints{};
                var direct_writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
                defer direct_writes.deinit(alloc);
                try direct_writes.appendSlice(alloc, req.graph_writes);
                for (extracted, 0..) |write, i| {
                    if (derived_changed_flags[i]) try direct_writes.appendSlice(alloc, write.graph_writes);
                }
                var notification_artifacts = std.ArrayListUnmanaged([]const u8).empty;
                defer notification_artifacts.deinit(alloc);
                try notification_artifacts.appendSlice(alloc, thin_changed_artifact_keys.items);
                for (deleted_artifact_keys) |key| try notification_artifacts.append(alloc, key);
                break :hints try directGraphNeighborContextHintsAlloc(alloc, req, direct_writes.items, notification_artifacts.items, active, owning_table);
            };
            defer neighbor_hints.deinit(alloc);
            if (neighbor_hints.keys.len > 0) try appendUniqueReplayRecordHint(alloc, &target_hints, .enrichment);
            for (neighbor_hints.keys) |key| try appendUniqueReplayRecordKeyWithSet(alloc, &changed_doc_keys, &changed_doc_key_set, key);

            for (req.deletes) |key| {
                try appendUniqueReplayRecordKeyWithSet(alloc, &deleted_doc_keys, &deleted_doc_key_set, key);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
            }
            for (deleted_artifact_keys) |key| {
                try appendUniqueReplayRecordKeyWithSet(alloc, &deleted_doc_keys, &deleted_doc_key_set, key);
                // Artifact removals advance the same source stream as upserts. Keep
                // them in the artifact-key lane so source-specific readiness cannot
                // report complete while a consumer still owes a delete.
                try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, key);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .dense_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .sparse_vector);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .algebraic);
                try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
                if (internal_keys.isAssetArtifactKey(key) or internal_keys.isChunkArtifactRecordKey(key) or internal_keys.isGraphEdgeArtifactKey(key)) {
                    try appendUniqueReplayRecordKeyWithSet(alloc, &thin_changed_artifact_keys, &thin_changed_artifact_key_set, key);
                    if (internal_keys.isChunkArtifactRecordKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .full_text);
                    try appendUniqueReplayRecordHint(alloc, &target_hints, .graph);
                    if (internal_keys.isAssetArtifactKey(key)) try appendUniqueReplayRecordHint(alloc, &target_hints, .resolution);
                }
            }

            var record: change_journal_mod.Record = .{ .sequence = sequence };
            defer change_journal_mod.deinitRecord(alloc, &record);
            record.changed_doc_keys = try changed_doc_keys.toOwnedSlice(alloc);
            record.deleted_doc_keys = try deleted_doc_keys.toOwnedSlice(alloc);
            record.overwritten_doc_keys = try overwritten_doc_keys.toOwnedSlice(alloc);
            record.changed_artifact_keys = try thin_changed_artifact_keys.toOwnedSlice(alloc);
            record.target_hints = try target_hints.toOwnedSlice(alloc);
            if (sync_targets_out) |out|
                out.* = try collectManagedSyncTargetsForRecord(alloc, index_manager.?, record);
            return try change_journal_mod.encodeRecord(alloc, record);
        }
        pub fn encodeTimestampValue(alloc: Allocator, timestamp_ns: u64) ![]u8 {
            const buf = try alloc.alloc(u8, 8);
            std.mem.writeInt(u64, buf[0..8], timestamp_ns, .little);
            return buf;
        }
        pub fn enforcePortableRuntimeGateOptional(pending: ?*const std.atomic.Value(bool)) !void {
            const configured = pending orelse return;
            if (configured.load(.acquire)) return error.PortableRuntimeActivationPending;
        }
        pub fn envBoolEnabled(raw: []const u8) bool {
            return !(std.mem.eql(u8, raw, "0") or
                std.ascii.eqlIgnoreCase(raw, "false") or
                std.ascii.eqlIgnoreCase(raw, "no"));
        }
        pub fn extractAssetSourceValue(
            alloc: Allocator,
            db: anytype,
            doc_value: []const u8,
            request: enrichment_types.GeneratedEnrichmentRequest,
        ) !?[]u8 {
            if (request.source_template.len > 0) {
                const rendered = renderSourceTemplateText(alloc, db, request.source_template, doc_value) catch |err| switch (err) {
                    error.OutOfMemory, error.PermanentPromptFailure, error.TransientPromptFailure => return err,
                    else => return null,
                };
                errdefer alloc.free(rendered);
                try document_extraction_mod.validateInlineSourceSize(db.remote_content, rendered);
                return @constCast(rendered);
            }

            const parsed = try std.json.parseFromSlice(std.json.Value, alloc, doc_value, .{ .parse_numbers = false });
            defer parsed.deinit();
            if (parsed.value != .object) return null;
            const source = parsed.value.object.get(request.source_field) orelse return null;
            return switch (source) {
                .null => null,
                .string => |value| blk: {
                    try document_extraction_mod.validateInlineSourceSize(db.remote_content, value);
                    break :blk try alloc.dupe(u8, value);
                },
                else => blk: {
                    const rendered = try std.json.Stringify.valueAlloc(alloc, source, .{});
                    errdefer alloc.free(rendered);
                    try document_extraction_mod.validateInlineSourceSize(db.remote_content, rendered);
                    break :blk rendered;
                },
            };
        }
        pub fn extractDocumentDownloadedAlloc(
            alloc: Allocator,
            downloaded: anytype,
            source_url: []const u8,
            config: document_extraction_mod.Config,
            config_json: []const u8,
            raw_document_json: []const u8,
            out_failure: *runtime_failure_abi.FailureIdentity,
        ) !document_extraction_mod.Result {
            out_failure.* = .{};
            if (comptime !builtin.is_test and build_options.linked_storage) {
                return document_extraction_client.extractDownloadedAllocWithLimitsWithFailure(
                    alloc,
                    downloaded,
                    source_url,
                    config_json,
                    raw_document_json,
                    config.pdf_decode_limits,
                    out_failure,
                );
            }
            return document_extraction_mod.extractDownloadedAlloc(alloc, downloaded, source_url, config);
        }
        pub fn extractStringField(alloc: Allocator, doc_value: []const u8, field_name: []const u8) !?[]u8 {
            const parsed = try std.json.parseFromSlice(std.json.Value, alloc, doc_value, .{});
            defer parsed.deinit();
            if (parsed.value != .object) return null;
            const field = parsed.value.object.get(field_name) orelse return null;
            if (field != .string) return null;
            return try alloc.dupe(u8, field.string);
        }
        pub fn extractionConfidenceForLocalId(entities: []const resolver_lib.ExtractedEntity, local_id: []const u8) ?f64 {
            for (entities) |entity| {
                if (std.mem.eql(u8, entity.local_id, local_id)) return entity.confidence;
            }
            return null;
        }
        pub fn extractionEntityForLocalId(entities: []const resolver_lib.ExtractedEntity, local_id: []const u8) ?resolver_lib.ExtractedEntity {
            for (entities) |entity| {
                if (std.mem.eql(u8, entity.local_id, local_id)) return entity;
            }
            return null;
        }
        pub fn filterAndRecordDenseEmbeddingArtifactRepairIssuesForReplay(
            ctx: *const AsyncContext,
            index_name: []const u8,
            dims: u32,
            owned: *OwnedDenseEmbeddingWrites,
            sequence: u64,
        ) !void {
            const ArtifactProbe = struct {
                artifact_key: []const u8,
                write_index: usize,

                fn lessThan(_: void, lhs: @This(), rhs: @This()) bool {
                    return switch (std.mem.order(u8, lhs.artifact_key, rhs.artifact_key)) {
                        .lt => true,
                        .eq => lhs.write_index < rhs.write_index,
                        .gt => false,
                    };
                }
            };

            var probes = std.ArrayListUnmanaged(ArtifactProbe).empty;
            defer probes.deinit(ctx.alloc);
            for (owned.writes, 0..) |write, write_index| {
                const artifact_key = write.artifact_key orelse continue;
                try probes.append(ctx.alloc, .{ .artifact_key = artifact_key, .write_index = write_index });
            }
            if (probes.items.len == 0) return;
            std.mem.sort(ArtifactProbe, probes.items, {}, ArtifactProbe.lessThan);

            const keys = try ctx.alloc.alloc([]const u8, probes.items.len);
            defer ctx.alloc.free(keys);
            const values = try ctx.alloc.alloc(?[]const u8, probes.items.len);
            defer ctx.alloc.free(values);
            for (probes.items, 0..) |probe, index| keys[index] = probe.artifact_key;

            // Replay consumes every artifact exactly once. Retaining these large
            // vector-bearing blocks both pollutes the foreground cache and duplicates
            // HBC's bounded native vector workspace. One sorted probe also avoids a
            // transaction and point lookup per embedding.
            var artifact_txn = try ctx.store.beginProbeTxnWithBlockCacheAdmission(.transient);
            defer artifact_txn.abort();
            try artifact_txn.getManySorted(keys, values);

            var removed_indices = std.ArrayListUnmanaged(usize).empty;
            defer removed_indices.deinit(ctx.alloc);
            for (probes.items, values) |probe, maybe_raw| {
                const write = owned.writes[probe.write_index];
                const reason = if (maybe_raw) |raw|
                    try denseEmbeddingArtifactRepairReasonFromRaw(ctx.alloc, dims, raw)
                else
                    types.ArtifactRepairReason.missing_artifact;
                if (reason) |repair_reason| {
                    // A delete can commit after this journal record but before replay
                    // reads its artifact. That is an ordinary supersession, not
                    // corruption: advance past the stale upsert and let the following
                    // delete record remove any indexed value. This also prevents TTL
                    // cleanup from wedging replay on an artifact it correctly removed.
                    if (repair_reason == .missing_artifact and !try denseEmbeddingWriteSourceDocumentExists(ctx, write)) {
                        try removed_indices.append(ctx.alloc, probe.write_index);
                        continue;
                    }
                    try recordEmbeddingArtifactRepairIssueContext(ctx, index_name, probe.artifact_key, sequence, repair_reason);
                }
            }
            if (removed_indices.items.len == 0) return;
            std.mem.sort(usize, removed_indices.items, {}, std.sort.asc(usize));

            const kept_len = owned.writes.len - removed_indices.items.len;
            const kept = try owned.alloc.alloc(mapper.DenseEmbeddingWrite, kept_len);
            var kept_idx: usize = 0;
            var removed_idx: usize = 0;
            for (owned.writes, 0..) |write, write_idx| {
                if (removed_idx < removed_indices.items.len and removed_indices.items[removed_idx] == write_idx) {
                    removed_idx += 1;
                    if (owned.owns_doc_keys) {
                        owned.alloc.free(@constCast(write.doc_key));
                        if (write.parent_doc_key) |parent_doc_key| owned.alloc.free(@constCast(parent_doc_key));
                    }
                    continue;
                }
                kept[kept_idx] = write;
                kept_idx += 1;
            }
            if (owned.allocation_len > 0) owned.alloc.free(owned.writes.ptr[0..owned.allocation_len]);
            owned.writes = kept;
            owned.allocation_len = kept.len;
        }
        pub fn filterAndRecordSparseEmbeddingArtifactRepairIssuesForReplay(
            ctx: *const AsyncContext,
            index_name: []const u8,
            owned: *OwnedSparseEmbeddingWrites,
            sequence: u64,
        ) !void {
            var removed_indices = std.ArrayListUnmanaged(usize).empty;
            defer removed_indices.deinit(ctx.alloc);
            for (owned.writes, 0..) |write, write_idx| {
                const artifact_key = write.artifact_key orelse continue;
                if (try sparseEmbeddingArtifactRepairReason(ctx, artifact_key)) |reason| {
                    // Sparse artifact cleanup follows the same primary/journal
                    // ordering as dense cleanup. If a later delete already removed
                    // both the source and artifact, this stale upsert is superseded;
                    // the later delete record remains responsible for index removal.
                    if (reason == .missing_artifact and !try replaySourceDocumentExists(ctx, write.doc_key)) {
                        try removed_indices.append(ctx.alloc, write_idx);
                        continue;
                    }
                    try recordEmbeddingArtifactRepairIssueContext(ctx, index_name, artifact_key, sequence, reason);
                }
            }
            if (removed_indices.items.len == 0) return;

            const kept_len = owned.writes.len - removed_indices.items.len;
            const kept = try owned.alloc.alloc(mapper.SparseEmbeddingWrite, kept_len);
            var kept_idx: usize = 0;
            var removed_idx: usize = 0;
            for (owned.writes, 0..) |write, write_idx| {
                if (removed_idx < removed_indices.items.len and removed_indices.items[removed_idx] == write_idx) {
                    removed_idx += 1;
                    continue;
                }
                kept[kept_idx] = write;
                kept_idx += 1;
            }
            if (owned.allocation_len > 0) owned.alloc.free(owned.writes.ptr[0..owned.allocation_len]);
            owned.writes = kept;
            owned.allocation_len = kept.len;
        }
        pub fn filterChangedGraphMaterializationBatch(
            alloc: Allocator,
            store: *docstore_mod.DocStore,
            writes: []const docstore_mod.KVPair,
            deletes: []const []const u8,
        ) !BorrowedGraphMaterializationBatch {
            var changed_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
            errdefer changed_writes.deinit(alloc);
            for (writes) |write| {
                if (try storeValueDiffers(alloc, store, write.key, write.value)) {
                    try changed_writes.append(alloc, write);
                }
            }

            var changed_deletes = std.ArrayListUnmanaged([]const u8).empty;
            errdefer changed_deletes.deinit(alloc);
            for (deletes) |key| {
                if (containsStoreWriteKey(writes, key)) continue;
                if (try storeContainsKey(alloc, store, key)) {
                    try changed_deletes.append(alloc, key);
                }
            }

            return .{
                .writes = try changed_writes.toOwnedSlice(alloc),
                .deletes = try changed_deletes.toOwnedSlice(alloc),
            };
        }
        pub fn findDocumentArtifactChildRange(
            ranges: []const types.DocumentArtifactChildRange,
            range_id: []const u8,
            range_kind: []const u8,
            artifact_name: []const u8,
        ) ?*const types.DocumentArtifactChildRange {
            for (ranges) |*range| {
                if (std.mem.eql(u8, range.range_id, range_id) and
                    std.mem.eql(u8, range.range_kind, range_kind) and
                    std.mem.eql(u8, range.artifact_name, artifact_name))
                {
                    return range;
                }
            }
            return null;
        }
        pub fn findOrAppendMentionEdgeAggregate(
            alloc: Allocator,
            aggregates: *std.ArrayListUnmanaged(MentionEdgeAggregate),
            target: []const u8,
            target_table: []const u8,
        ) !*MentionEdgeAggregate {
            for (aggregates.items) |*existing| {
                if (std.mem.eql(u8, existing.target, target)) return existing;
            }
            const target_owned = try alloc.dupe(u8, target);
            var target_owned_live = true;
            errdefer if (target_owned_live) alloc.free(target_owned);
            const table_owned = try alloc.dupe(u8, target_table);
            var table_owned_live = true;
            errdefer if (table_owned_live) alloc.free(table_owned);
            try aggregates.append(alloc, .{
                .target = target_owned,
                .target_table = table_owned,
                .mention_confidence = 0,
            });
            target_owned_live = false;
            table_owned_live = false;
            return &aggregates.items[aggregates.items.len - 1];
        }
        pub fn finishManagedSyncTargets(
            alloc: Allocator,
            full_text_indexes: *std.ArrayListUnmanaged([]const u8),
            all_indexes: *std.ArrayListUnmanaged([]const u8),
            target_identities: *std.ArrayListUnmanaged(IndexTargetVisibility),
            target_scope_known: bool,
        ) !ManagedSyncTargets {
            const owned_full_text = try full_text_indexes.toOwnedSlice(alloc);
            errdefer {
                for (owned_full_text) |name| alloc.free(@constCast(name));
                if (owned_full_text.len > 0) alloc.free(owned_full_text);
            }
            const owned_all = try all_indexes.toOwnedSlice(alloc);
            errdefer {
                for (owned_all) |name| alloc.free(@constCast(name));
                if (owned_all.len > 0) alloc.free(owned_all);
            }
            var identities: []IndexTargetVisibility = &.{};
            if (target_scope_known) {
                identities = try target_identities.toOwnedSlice(alloc);
            } else {
                for (target_identities.items) |identity| alloc.free(@constCast(identity.index_name));
                target_identities.deinit(alloc);
                target_identities.* = .empty;
            }

            return .{
                .full_text_indexes = owned_full_text,
                .all_indexes = owned_all,
                .target_identities = identities,
                .target_scope_known = target_scope_known,
            };
        }
        pub fn flushGeneratedDenseChunkBatch(
            alloc: Allocator,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
            dense_embedder: embedder_mod.DenseEmbedder,
            embedding_name: []const u8,
            request: enrichment_types.GeneratedEnrichmentRequest,
            artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
            dense_embeddings: anytype,
            sources: []const ChunkEmbeddingSource,
            source_indexes: *std.ArrayListUnmanaged(usize),
            chunk_texts: *std.ArrayListUnmanaged([]const u8),
            consumer_indexes: []const []const u8,
            comptime appendForConsumers: anytype,
        ) !void {
            if (chunk_texts.items.len == 0) return;

            const vectors = try enrichment_runtime_mod.embedDenseBatchTracked(runtime, consumer_indexes, alloc, dense_embedder, embedding_name, chunk_texts.items, request.expected_dims);
            defer embedder_mod.freeDenseEmbeddingBatch(alloc, vectors);
            if (vectors.len != source_indexes.items.len) return error.InvalidEmbeddingResponse;

            for (source_indexes.items, vectors) |source_index, vector| {
                const source = sources[source_index];
                const artifact_key = try appendEmbeddingArtifactWrite(
                    alloc,
                    artifact_writes,
                    source.key,
                    request.doc_key,
                    embedding_name,
                    request.source_field,
                    source.key,
                    .{ .generated = enrichment_artifact_codec.hashEmbeddingSource(source.text, request.producer_json) },
                    vector,
                );
                defer alloc.free(artifact_key);
                try appendForConsumers(alloc, dense_embeddings, source.key, request.doc_key, artifact_key, vector, consumer_indexes);
            }

            chunk_texts.clearRetainingCapacity();
            source_indexes.clearRetainingCapacity();
        }
        pub fn flushGeneratedDenseChunkSourceBatch(
            alloc: Allocator,
            db: anytype,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
            dense_embedder: embedder_mod.DenseEmbedder,
            embedding_name: []const u8,
            request: enrichment_types.GeneratedEnrichmentRequest,
            artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
            dense_embeddings: anytype,
            sources: *std.ArrayListUnmanaged(ChunkEmbeddingSource),
            consumer_indexes: []const []const u8,
            skip_unchanged_artifacts: bool,
            pending_lookup: ?*const PendingArtifactWriteIndex,
            comptime appendForConsumers: anytype,
        ) !void {
            if (sources.items.len == 0) return;
            defer clearChunkEmbeddingSourceList(alloc, sources);

            var chunk_texts = std.ArrayListUnmanaged([]const u8).empty;
            defer chunk_texts.deinit(alloc);
            var source_indexes = std.ArrayListUnmanaged(usize).empty;
            defer source_indexes.deinit(alloc);

            for (sources.items, 0..) |source, i| {
                const source_hash = enrichment_artifact_codec.hashEmbeddingSource(source.text, request.producer_json);
                const artifact_key = try embeddingArtifactKeyForBaseAlloc(alloc, source.key, embedding_name);
                defer alloc.free(artifact_key);
                if (skip_unchanged_artifacts) {
                    if (try storedOrPendingEmbeddingSourceHash(db, pending_lookup, artifact_key)) |existing_hash| {
                        if (existing_hash == source_hash) {
                            try appendForConsumers(alloc, dense_embeddings, source.key, request.doc_key, artifact_key, &.{}, consumer_indexes);
                            continue;
                        }
                    }
                }
                try chunk_texts.append(alloc, source.text);
                try source_indexes.append(alloc, i);
            }

            try flushGeneratedDenseChunkBatch(alloc, runtime, dense_embedder, embedding_name, request, artifact_writes, dense_embeddings, sources.items, &source_indexes, &chunk_texts, consumer_indexes, appendForConsumers);
        }
        pub fn flushGeneratedDenseMemoJobs(
            self: anytype,
            memo: *GeneratedEmbeddingMemo,
            jobs: *std.ArrayListUnmanaged(GeneratedDenseMemoJob),
        ) !void {
            if (jobs.items.len == 0) return;
            defer clearGeneratedDenseMemoJobs(memo.alloc, jobs);
            const runtime = self.enrichment_runtime orelse return;
            const embedder = runtime.config.dense_embedder orelse return;
            const texts = try memo.alloc.alloc([]const u8, jobs.items.len);
            defer memo.alloc.free(texts);
            for (jobs.items, texts) |job, *text| text.* = job.text;
            const first = jobs.items[0].request;
            const vectors = try enrichment_runtime_mod.embedDenseBatchTracked(
                runtime,
                first.consumer_indexes,
                memo.alloc,
                embedder,
                requestEmbeddingName(first),
                texts,
                first.expected_dims,
            );
            defer embedder_mod.freeDenseEmbeddingBatch(memo.alloc, vectors);
            for (jobs.items, vectors) |job, vector| try memo.putDenseCopy(job.key, vector);
        }
        pub fn flushGeneratedSparseChunkBatch(
            alloc: Allocator,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
            sparse_embedder: embedder_mod.SparseEmbedder,
            embedding_name: []const u8,
            semantic_producer: []const u8,
            artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
            sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
            sources: []const ChunkEmbeddingSource,
            source_indexes: *std.ArrayListUnmanaged(usize),
            chunk_texts: *std.ArrayListUnmanaged([]const u8),
            consumer_indexes: []const []const u8,
        ) !void {
            if (chunk_texts.items.len == 0) return;

            const sparse_batch = try enrichment_runtime_mod.embedSparseBatchTracked(runtime, consumer_indexes, alloc, sparse_embedder, embedding_name, chunk_texts.items);
            defer embedder_mod.freeSparseEmbeddingBatch(alloc, sparse_batch);
            if (sparse_batch.len != source_indexes.items.len) return error.InvalidEmbeddingResponse;

            for (source_indexes.items, sparse_batch) |source_index, sparse| {
                const source = sources[source_index];
                const artifact_key = try appendSparseEmbeddingArtifactWrite(
                    alloc,
                    artifact_writes,
                    source.key,
                    embedding_name,
                    .{ .generated = enrichment_artifact_codec.hashEmbeddingSource(source.text, semantic_producer) },
                    sparse.indices,
                    sparse.values,
                );
                defer alloc.free(artifact_key);
                try appendDerivedSparseEmbeddingForConsumers(alloc, sparse_embeddings, source.key, artifact_key, sparse.indices, sparse.values, consumer_indexes);
            }

            chunk_texts.clearRetainingCapacity();
            source_indexes.clearRetainingCapacity();
        }
        pub fn flushGeneratedSparseChunkSourceBatch(
            alloc: Allocator,
            db: anytype,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
            sparse_embedder: embedder_mod.SparseEmbedder,
            embedding_name: []const u8,
            semantic_producer: []const u8,
            artifact_writes: *std.ArrayListUnmanaged(types.BatchWrite),
            sparse_embeddings: *std.ArrayListUnmanaged(derived_types.DerivedSparseEmbeddingWrite),
            sources: *std.ArrayListUnmanaged(ChunkEmbeddingSource),
            consumer_indexes: []const []const u8,
