        pub fn flushPendingDenseChunkEmbedding(
            alloc: Allocator,
            runtime: *enrichment_runtime_mod.EnrichmentRuntime,
            dense_embedder: embedder_mod.DenseEmbedder,
            doc_key: []const u8,
