                alloc,
                runtime,
                dense_embedder,
                pending.embedding_name,
                synthetic_request,
                artifact_writes,
                dense_embeddings,
                pending.sources.items,
                &pending.source_indexes,
                &pending.chunk_texts,
                pending.consumer_indexes,
                appendDerivedDenseEmbeddingForConsumers,
            );
            pending.batch_source_bytes = 0;
