        pub fn takeOwnedSlice(comptime T: type, alloc: Allocator, existing: []const T, incoming: *[]const T) ![]const T {
            if (incoming.*.len == 0) return existing;
            if (existing.len == 0) {
                const out = incoming.*;
                incoming.* = &.{};
                return out;
            }

            const out = try alloc.alloc(T, existing.len + incoming.*.len);
            @memcpy(out[0..existing.len], existing);
            @memcpy(out[existing.len..], incoming.*);
            alloc.free(existing);
            alloc.free(incoming.*);
            incoming.* = &.{};
            return out;
        }
        pub fn truncateReplayJournalIfSafeContext(ctx: *const BatchExecutionContext) !void {
            if (ctx.repair_replay_mutex) |mutex| mutex.lockUncancelable(ctx.index_manager.checkpointIo());
            defer if (ctx.repair_replay_mutex) |mutex| mutex.unlock(ctx.index_manager.checkpointIo());
            if (!ctx.index_manager.hasManagedIndexes()) return;

            const managed_indexes = try ctx.index_manager.managedIndexes(ctx.alloc);
            defer {
                for (managed_indexes) |index_ref| ctx.alloc.free(@constCast(index_ref.name));
                ctx.alloc.free(managed_indexes);
            }
            if (managed_indexes.len == 0) return;

            var min_applied: u64 = std.math.maxInt(u64);
            for (managed_indexes) |index_ref| {
                const applied = try loadManagedAppliedSequenceContext(
                    ctx.alloc,
                    ctx.index_manager,
                    ctx.store,
                    ctx.applied_sequence_checkpoint_path,
                    index_ref,
                );
                min_applied = @min(min_applied, applied);
            }
            if (ctx.index_manager.hasGeneratedEnrichmentTargets()) {
                const enrichment_applied = try enrichment_state.loadAppliedSequence(
                    ctx.alloc,
                    ctx.store,
                    enrichment_runtime_mod.scope_name,
                );
                min_applied = @min(min_applied, enrichment_applied);
            }
            if (ctx.resolution_runtime) |runtime| {
                const stats = runtime.stats();
                if (resolverReplayRetentionRequired(ctx.index_manager, stats)) {
                    min_applied = @min(min_applied, stats.applied_sequence);
                }
            }
            if (ctx.promotion_runtime) |runtime| {
                const stats = runtime.stats();
                if (resolverReplayRetentionRequired(ctx.index_manager, stats)) {
                    min_applied = @min(min_applied, stats.applied_sequence);
                }
            }
            min_applied = try clampReplayTruncationForRepairPins(ctx.alloc, ctx.index_repair_checkpoint, min_applied);
            if (min_applied == 0 or min_applied == std.math.maxInt(u64)) return;
            try truncateReplayLogs(ctx, min_applied);
        }
        pub fn truncateReplayLogs(ctx: *const BatchExecutionContext, up_to_sequence: u64) !void {
            try ctx.store.truncateReplayUpTo(ctx.alloc, up_to_sequence);
            ctx.executor.releaseBacklogThrough(up_to_sequence);
        }
        pub fn ttlTimestampNsFromDocumentValue(
            alloc: Allocator,
            schema: schema_mod.TableSchema,
            value_json: []const u8,
        ) !?u64 {
            var parsed = try std.json.parseFromSlice(std.json.Value, alloc, value_json, .{});
            defer parsed.deinit();
            const root = switch (parsed.value) {
                .object => |object| object,
                else => return null,
            };
            const ttl_value = root.get(schema.ttl_field) orelse return null;
            if (ttl_value == .null) return null;
            return try ttlTimestampNsFromJsonValue(ttl_value);
        }
        pub fn ttlTimestampNsFromJsonValue(value: std.json.Value) !u64 {
            return switch (value) {
                .integer => |integer| blk: {
                    if (integer < 0) return error.InvalidArgument;
                    break :blk std.math.cast(u64, integer) orelse return error.InvalidArgument;
                },
                .number_string => |text| std.fmt.parseInt(u64, std.mem.trim(u8, text, " \t\r\n"), 10) catch return error.InvalidArgument,
                .string => |text| ttlTimestampNsFromString(text),
                else => error.InvalidArgument,
            };
        }
        pub fn ttlTimestampNsFromString(text: []const u8) !u64 {
            const trimmed = std.mem.trim(u8, text, " \t\r\n");
            if (trimmed.len == 0) return error.InvalidArgument;
            if (std.fmt.parseInt(u64, trimmed, 10)) |ts| return ts else |_| {}
            if (try parsePatternRfc3339ToNs(trimmed)) |ts| return ts;
            return error.InvalidArgument;
        }
        pub fn unitDescriptorFingerprintMatches(descriptors: []const DocumentExtractionUnitDescriptor, key: []const u8, fingerprint: []const u8) bool {
            if (fingerprint.len == 0) return false;
            for (descriptors) |descriptor| {
