            }
            return false;
        }
        pub fn unlockProfiledApply(
            self: anytype,
            profile: ?*BatchProfile,
            held: *bool,
            acquired_ns: u64,
        ) void {
            std.debug.assert(held.*);
            if (profile) |active_profile| active_profile.apply_lock_held_ns += monotonicTimeNs() - acquired_ns;
            self.core.unlockApply();
